// ----------------------------------------------------
// Indonesian Terbilang Logic
// ----------------------------------------------------
function angkaKeTerbilang(nominal) {
  const units = ["", "Satu", "Dua", "Tiga", "Empat", "Lima", "Enam", "Tujuh", "Delapan", "Sembilan", "Sepuluh", "Sebelas"];
  
  function convert(n) {
    if (n < 0) return "Minus " + convert(Math.abs(n));
    if (n < 12) return units[n];
    if (n < 20) return convert(n - 10) + " Belas";
    if (n < 100) return convert(Math.floor(n / 10)) + " Puluh " + convert(n % 10);
    if (n < 200) return "Seratus " + convert(n - 100);
    if (n < 1000) return convert(Math.floor(n / 100)) + " Ratus " + convert(n % 100);
    if (n < 2000) return "Seribu " + convert(n - 1000);
    if (n < 1000000) return convert(Math.floor(n / 1000)) + " Ribu " + convert(n % 1000);
    if (n < 1000000000) return convert(Math.floor(n / 1000000)) + " Juta " + convert(n % 1000000);
    if (n < 1000000000000) return convert(Math.floor(n / 1000000000)) + " Milyar " + convert(n % 1000000000);
    if (n < 1000000000000000) return convert(Math.floor(n / 1000000000000)) + " Triliun " + convert(n % 1000000000000);
    return "";
  }

  // Sanitasi input integer
  const val = Math.floor(Math.abs(nominal));
  if (val === 0) return "Nol Rupiah";
  
  // Format clean string
  let result = convert(val).replace(/\s+/g, ' ').trim();
  
  // Custom replacements for standard Indonesian formatting (e.g. "Satu Ratus" -> "Seratus", "Satu Ribu" -> "Seribu")
  // (Note: Already handled by < 200 and < 2000 conditions, but double check cleanup)
  result = result.replace("Satu Puluh", "Sepuluh");
  
  return result + " Rupiah";
}

// ----------------------------------------------------
// Formatter Helpers
// ----------------------------------------------------
function formatRupiah(amount, withPrefix = false) {
  const number = Number(amount) || 0;
  // Format value to 2 decimal places using Indonesian locale (id-ID)
  // Which uses period (.) as thousands separator and comma (,) as decimal separator
  const formatted = number.toLocaleString("id-ID", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
  return withPrefix ? `Rp ${formatted}` : formatted;
}

function formatKuantitas(amount) {
  const number = Number(amount) || 0;
  // Format with comma decimals, e.g. 65,10
  return number.toLocaleString("id-ID", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function formatDateIndo(dateStr) {
  if (!dateStr) return "";
  const parts = dateStr.split("-"); // YYYY-MM-DD
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}/${parts[1]}/${parts[0]}`; // DD/MM/YYYY
}

function getIndonesianDateText(dateStr) {
  if (!dateStr) return "";
  const parts = dateStr.split("-"); // YYYY-MM-DD
  if (parts.length !== 3) return "";
  const day = parseInt(parts[2]);
  const monthNames = [
    "JANUARI", "FEBRUARI", "MARET", "APRIL", "MEI", "JUNI",
    "JULI", "AGUSTUS", "SEPTEMBER", "OKTOBER", "NOVEMBER", "DESEMBER"
  ];
  const month = monthNames[parseInt(parts[1]) - 1] || "";
  const year = parts[0];
  return `${day} ${month} ${year}`;
}

