// ----------------------------------------------------
function updatePreview() {
  const activeInv = invoices.find(inv => inv.id === activeInvoiceId);
  if (!activeInv) return;

  // Metadata
  elViewRef.innerText = activeInv.ref || "-";
  elViewDate.innerText = formatDateIndo(activeInv.date);
  elViewDueDate.innerText = formatDateIndo(activeInv.dueDate);

  // Logo Preview Toggle
  if (activeInv.logo) {
    elViewLogoImg.src = activeInv.logo;
    elViewLogoImg.style.display = "block";
    elViewLogoBox.style.display = "flex";
    elBtnRemoveLogo.style.display = "inline-block";
  } else {
    elViewLogoImg.src = "";
    elViewLogoImg.style.display = "none";
    elViewLogoBox.style.display = "none";
    elBtnRemoveLogo.style.display = "none";
  }

  // Address
  elViewCompanyName.innerText = activeInv.company?.name || "";
  elViewCompanyAddress.innerText = activeInv.company?.address || "";
  elViewCompanyPhone.innerText = activeInv.company?.phone || "";
  elViewCompanyEmail.innerText = activeInv.company?.email || "";

  elViewClientName.innerText = activeInv.client?.name || "";
  elViewClientAddress.innerText = activeInv.client?.address || "";
  elViewClientEmail.innerText = activeInv.client?.email || "";

  // Notes
  elViewNotes.innerText = activeInv.notes || "";

  // Items Render
  elViewItemsContainer.innerHTML = "";
  let subtotal = 0;
  
  activeInv.items.forEach(item => {
    const itemTotal = item.quantity * item.price;
    subtotal += itemTotal;

    const tr = document.createElement("tr");
    tr.innerHTML = `
      <td class="col-urai">${item.description || ""}</td>
      <td class="col-qty">${item.qtyUnit || ""}</td>
      <td class="col-kuan">${formatKuantitas(item.quantity)}</td>
      <td class="col-harga">${formatRupiah(item.price)}</td>
      <td class="col-jumlah">${formatRupiah(itemTotal)}</td>
    `;
    elViewItemsContainer.appendChild(tr);
  });

  // Calculate Subtotal & Total (directly equal in this template)
  const total = subtotal;

  elViewSubtotal.innerText = formatRupiah(subtotal, true);
  elViewTotal.innerText = formatRupiah(total, true);

  // Indonesian Terbilang Text
  elViewTerbilang.innerText = angkaKeTerbilang(total);

  // Signer Details
  elViewSignerName.innerText = activeInv.signerName || "AHMAD ROFIQ";
  elViewSignerRole.innerText = activeInv.signerRole || "Direktur";

  // Signature rendering
  if (activeInv.signature) {
    elViewSigImg.src = activeInv.signature;
    elViewSigImg.style.display = "block";
    elViewSigPlaceholder.style.display = "none";
  } else {
    elViewSigImg.style.display = "none";
    elViewSigPlaceholder.style.display = "block";
  }

  // Stempel Company Stamp rendering
  if (elViewStampContainer) {
    const elViewStampImg = document.getElementById("view-stamp-img");
    if (activeInv.showStamp !== false && (activeInv.company?.name === "PT. AR MULTI KARYA" || activeInv.showStamp)) {
      if (elViewStampImg) {
        elViewStampImg.src = activeInv.stamp || (typeof STAMP_PT_AR_MULTI_KARYA !== "undefined" ? STAMP_PT_AR_MULTI_KARYA : "stempel_ar_multi_karya-removebg-preview.png");
      }
      elViewStampContainer.style.display = "block";
    } else {
      elViewStampContainer.style.display = "none";
    }
  }

  // Update current list metadata display without complete list redraw
  const activeListItem = document.querySelector(`.invoice-item-btn[data-id="${activeInvoiceId}"]`);
  if (activeListItem) {
    activeListItem.querySelector(".invoice-item-title").innerText = activeInv.ref || "Draft Invoice";
    activeListItem.querySelector(".invoice-item-meta span:first-child").innerText = formatDateIndo(activeInv.date);
    activeListItem.querySelector(".invoice-item-meta span:last-child").innerText = formatRupiah(total, true);
  }
}

